7	/**
8	 * 指纹工具：对 requestId、操作类型与全部业务字段计算 SHA-256。
9	 * 业务字段先由调用方序列化为规范化 JSON 字节，保证同参指纹一致。
10	 */
11	public final class Fingerprints {
12	
13	    private Fingerprints() {
14	    }
15	
16	    /**
17	     * 计算指纹：requestId 与操作类型显式入指纹，防止跨操作复用键。
18	     */
19	    public static String sha256(String requestId, String operation, byte[] normalizedBusinessJson) {
20	        MessageDigest digest;
21	        try {
22	            digest = MessageDigest.getInstance("SHA-256");
23	        } catch (NoSuchAlgorithmException e) {
24	            throw new IllegalStateException("SHA-256 unavailable", e);
25	        }
26	        digest.update(requestId.getBytes(StandardCharsets.UTF_8));
27	        digest.update((byte) 0);
28	        digest.update(operation.getBytes(StandardCharsets.UTF_8));
29	        digest.update((byte) 0);
30	        digest.update(normalizedBusinessJson);
31	        byte[] hash = digest.digest();
32	        StringBuilder hex = new StringBuilder(hash.length * 2);
33	        for (byte b : hash) {
34	            hex.append(Character.forDigit((b >> 4) & 0xF, 16));
35	            hex.append(Character.forDigit(b & 0xF, 16));
36	        }
37	        return hex.toString();
38	    }
39	}
