3	import static org.assertj.core.api.Assertions.assertThat;
4	
5	import java.time.Duration;
6	
7	import org.junit.jupiter.api.DisplayName;
8	import org.junit.jupiter.api.Test;
9	import org.springframework.beans.factory.annotation.Autowired;
10	
11	import com.example.starter.api.dto.WitnessResult;
12	import com.example.starter.testsupport.AbstractServiceTest;
13	import com.example.starter.testsupport.TestClockConfig;
14	import com.example.starter.testsupport.TestRequests;
15	
16	/**
17	 * H 点见证流程测试：缺席转等待、等待满 2 小时（含恰满边界）升级、
18	 * 未见证不得进入覆盖工序、见证到场后放行。
19	 */
20	class WitnessFlowServiceTest extends AbstractServiceTest {
21	
22	    @Autowired
23	    private OperationService service;
24	
25	    /** 派工 H 点卡 → 力矩合格 → 自检互检完成，返回卡号。 */
26	    private String prepareInspectedHCard(String cardNo, String station) {
27	        service.registerTool(TestRequests.tool("T1", TestRequests.TODAY));
28	        service.dispatch(TestRequests.singlePoint("d-" + cardNo, cardNo, station, "H", "P1", "100.000"));
29	        service.measure(TestRequests.torque("m-" + cardNo, cardNo, "P1", "100.000", "op1", "T1"));
30	        service.inspect(TestRequests.inspection("i-" + cardNo, cardNo, "self-A", "mutual-B"));
31	        return cardNo;
32	    }
33	
34	    @Test
35	    @DisplayName("见证缺席转等待，升级时刻为缺席起恰满 2 小时")
36	    void absentTransitionsToWaiting() {
37	        prepareInspectedHCard("CARD-W1", "S1");
38	
39	        Outcome absent = service.witness(TestRequests.witnessAbsent("w-absent", "CARD-W1"));
40	        assertThat(absent.status()).isEqualTo(200);
41	        WitnessResult result = (WitnessResult) absent.body();
42	        assertThat(result.witnessStatus()).isEqualTo("WAITING");
43	        assertThat(result.cardStatus()).isEqualTo("WAITING_WITNESS");
44	        assertThat(result.escalated()).isFalse();
45	        assertThat(result.escalateAt()).isEqualTo(TestClockConfig.FIXED_NOW.plus(Duration.ofHours(2)));
46	    }
47	
48	    @Test
49	    @DisplayName("等待未满 2 小时不升级；恰满 2 小时（边界）升级，覆盖工序仍被拒绝")
50	    void exactlyTwoHoursTriggersEscalation() {
51	        prepareInspectedHCard("CARD-W2", "S2");
52	        service.witness(TestRequests.witnessAbsent("w-absent", "CARD-W2"));
53	
54	        // 未见证不得进入覆盖工序
55	        Outcome blocked = service.coverage(TestRequests.coverage("cov-blocked", "CARD-W2"));
56	        assertThat(blocked.status()).isEqualTo(422);
57	        assertThat(((java.util.Map<?, ?>) blocked.body()).get("errorCode")).isEqualTo("WITNESS_REQUIRED");
58	
59	        // 差 1 秒未满：不升级
60	        clock.advance(Duration.ofHours(2).minusSeconds(1));
61	        Outcome notYet = service.checkEscalation("CARD-W2");
62	        WitnessResult notYetResult = (WitnessResult) notYet.body();
63	        assertThat(notYetResult.escalated()).isFalse();
64	        assertThat(service.getCard("CARD-W2").status()).isEqualTo("WAITING_WITNESS");
65	
66	        // 恰满 2 小时：升级
67	        clock.advance(Duration.ofSeconds(1));
68	        Outcome escalated = service.checkEscalation("CARD-W2");
69	        WitnessResult escalatedResult = (WitnessResult) escalated.body();
70	        assertThat(escalatedResult.escalated()).isTrue();
71	        assertThat(escalatedResult.witnessStatus()).isEqualTo("ESCALATED");
72	        assertThat(service.getCard("CARD-W2").status()).isEqualTo("ESCALATED");
73	
74	        // 升级后仍未见证，覆盖继续被拒绝
75	        Outcome stillBlocked = service.coverage(TestRequests.coverage("cov-blocked-2", "CARD-W2"));
76	        assertThat(stillBlocked.status()).isEqualTo(422);
77	
78	        // 升级检查幂等：再次检查保持 ESCALATED，不重复追加链
79	        Outcome recheck = service.checkEscalation("CARD-W2");
80	        assertThat(((WitnessResult) recheck.body()).escalated()).isTrue();
81	        assertThat(service.trace("CARD-W2").witnessChain())
82	                .extracting(com.example.starter.api.dto.TraceView.WitnessPoint::status)
83	                .filteredOn("ESCALATED"::equals)
84	                .hasSize(1);
85	    }
86	
87	    @Test
88	    @DisplayName("等待期间见证人到场：转 WITNESSED，允许覆盖工序并放行归档")
89	    void witnessArrivesDuringWaiting() {
90	        prepareInspectedHCard("CARD-W3", "S3");
91	        service.witness(TestRequests.witnessAbsent("w-absent", "CARD-W3"));
92	        clock.advance(Duration.ofMinutes(30));
93	
94	        Outcome present = service.witness(TestRequests.witnessPresent("w-present", "CARD-W3", "witness-Q"));
95	        WitnessResult presentResult = (WitnessResult) present.body();
96	        assertThat(presentResult.witnessStatus()).isEqualTo("PRESENT");
97	        assertThat(service.getCard("CARD-W3").status()).isEqualTo("WITNESSED");
98	
99	        Outcome coverage = service.coverage(TestRequests.coverage("cov-ok", "CARD-W3"));
100	        assertThat(coverage.status()).isEqualTo(200);
101	
102	        Outcome release = service.release(TestRequests.release("rel-ok", "CARD-W3", "qa-lead"));
103	        assertThat(release.status()).isEqualTo(200);
104	        assertThat(service.getCard("CARD-W3").status()).isEqualTo("ARCHIVED");
105	    }
106	
107	    @Test
108	    @DisplayName("H 点未见证直接放行被拒绝；到场缺见证人姓名被 400 拒绝")
109	    void releaseWithoutWitnessRejected() {
110	        prepareInspectedHCard("CARD-W4", "S4");
111	
112	        Outcome releaseBlocked = service.release(TestRequests.release("rel-blocked", "CARD-W4", "qa"));
113	        assertThat(releaseBlocked.status()).isEqualTo(422);
114	        assertThat(((java.util.Map<?, ?>) releaseBlocked.body()).get("errorCode"))
115	                .isEqualTo("WITNESS_REQUIRED");
116	
117	        Outcome noName = service.witness(
118	                new com.example.starter.api.dto.WitnessRequest("w-noname", "CARD-W4", "PRESENT", "  "));
119	        assertThat(noName.status()).isEqualTo(400);
120	        assertThat(((java.util.Map<?, ?>) noName.body()).get("errorCode"))
121	                .isEqualTo("WITNESS_NAME_REQUIRED");
122	    }
123	
124	    @Test
125	    @DisplayName("非 H 点工序无需见证：自检互检后即可覆盖与放行")
126	    void nonHPointSkipsWitness() {
127	        service.registerTool(TestRequests.tool("T1", TestRequests.TODAY));
128	        service.dispatch(TestRequests.singlePoint("d-w5", "CARD-W5", "S5", "N", "P1", "100.000"));
129	        service.measure(TestRequests.torque("m-w5", "CARD-W5", "P1", "100", "op1", "T1"));
130	        service.inspect(TestRequests.inspection("i-w5", "CARD-W5", "a", "b"));
131	
132	        assertThat(service.coverage(TestRequests.coverage("cov-w5", "CARD-W5")).status()).isEqualTo(200);
133	        assertThat(service.release(TestRequests.release("rel-w5", "CARD-W5", "qa")).status()).isEqualTo(200);
134	    }
135	}
