            TestRequests.packet(1, "P1", "2026-09-26T08:00:01Z", "100.000"),
            TestRequests.packet(3, "P3", "2026-09-26T08:00:03Z", "50.000")));
    assertThat(acquisitionService.getWatermark("SES-A2").watermark()).isEqualTo(1);
